def test_preserve_col_structure(grid):
    """For each column, compute the sorted output per column independently"""
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for c in range(cols):
        col = [grid[r][c] for r in range(rows)]
        counts = {}
        for v in col:
            counts[v] = counts.get(v, 0) + 1

        # Recreate column with same counts
        v = 0
        output = []
        while v <= 9:
            if v in counts:
                output.extend([v] * counts.pop(v))
            v += 1

